-- iKYEM demo: four months of work history for the Team screen (15 June to 13 October 2026)
--
-- The factory works Thursday to Tuesday with Wednesday off, and pays every Tuesday for that
-- Thursday-to-Tuesday week. This script also sets Setup's factory settings to that.
--
-- Run "npm run db:migrate" against this branch first (the settings need the weekly holiday column).
-- Run ONLY on the demo copy of the database (the Neon branch with the demo team), never on real data.
-- It refuses to run unless the demo team, ball types, materials, suppliers and grades are there by
-- name, and unless 15 Jun - 14 Oct 2026 has no daily sheets yet. If it refuses, nothing is changed.
--
-- What it adds (all marked 'demo-seed' so it can be removed again):
--   * a daily sheet for every working day (no Wednesdays): attendance, every stage's work by
--     person, and grading (15 Aug and 2 Oct are marked as closed days),
--   * leather and cork purchases as stock runs low, at the demo prices,
--   * Tuesday pay (Thursday to Tuesday) marked paid for every payday from 16 Jun to 13 Oct, and month-end salaries for
--     July, August and September, worked out from these sheets the same way the Pay screen does.
--
-- To remove it again:
--   BEGIN;
--   DELETE FROM day_sheets WHERE updated_by = 'demo-seed';   -- also removes their attendance, work and grading
--   DELETE FROM wage_payments WHERE created_by = 'demo-seed';
--   DELETE FROM purchases WHERE created_by = 'demo-seed';
--   COMMIT;

BEGIN;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'factory_settings' AND column_name = 'weekly_off') THEN
    RAISE EXCEPTION 'Run "npm run db:migrate" against this database branch first. Nothing was changed.';
  END IF;
  IF (SELECT count(*) FROM workers WHERE name IN ('Manoj Deshmukh', 'Ajay Kulkarni', 'Imran Shaikh', 'Ramesh Patil', 'Suresh Jadhav', 'Pooja More', 'Sunita Pawar', 'Raju Gaikwad', 'Vikas Shinde')) < 9
     OR (SELECT count(*) FROM ball_types WHERE name IN ('Red 4-piece', 'White 4-piece', 'Pink 2-piece', 'Red 4-piece machine', 'Red 2-piece machine')) < 5
     OR (SELECT count(*) FROM materials WHERE name IN ('Red leather, alum tanned', 'Red leather, chrome tanned', 'White leather', 'Pink leather', 'Cork core')) < 5
     OR (SELECT count(*) FROM suppliers WHERE name IN ('Kanpur Tanners', 'Jalandhar Leather Co', 'Meerut Cork Works')) < 3
     OR (SELECT count(*) FROM grades WHERE name IN ('Grade A', 'Grade B', 'Practice')) < 3 THEN
    RAISE EXCEPTION 'This is not the demo database: the demo team, ball types, materials, suppliers or grades are missing. Nothing was changed.';
  END IF;
  IF EXISTS (SELECT 1 FROM day_sheets WHERE day BETWEEN '2026-06-15' AND '2026-10-13') THEN
    RAISE EXCEPTION 'Some days between 2026-06-15 and 2026-10-13 already have daily sheets. Nothing was changed.';
  END IF;
END $$;

INSERT INTO factory_settings (id, weekly_off, pay_weekday) VALUES (1, 3, 2)
ON CONFLICT (id) DO UPDATE SET weekly_off = 3, pay_weekday = 2;

