) AS v(day, n, stage, person, ball_type, good, rejected, leather, supplier, sheets)
LEFT JOIN workers w ON w.name = v.person
JOIN ball_types b ON b.name = v.ball_type
LEFT JOIN materials m ON m.name = v.leather
LEFT JOIN suppliers s ON s.name = v.supplier;

