-- Tuesday pay, the same sum as the Pay screen, for the work week Thursday to that Tuesday (the
-- Wednesday before it is the holiday): days present (half = 0.5) x daily wage, or good pieces
-- x piece rate, less advances that week; salaried staff get their weekly payout.
WITH paydays AS (SELECT d::date AS payday FROM generate_series(date '2026-06-16', date '2026-10-13', interval '7 days') d),
due AS (
  SELECT w.id AS worker_id, p.payday,
    CASE w.pay_type
      WHEN 'daily' THEN round(coalesce((SELECT sum(CASE a.status WHEN 'present' THEN 1 WHEN 'half' THEN 0.5 ELSE 0 END)
                                         FROM attendance a WHERE a.worker_id = w.id AND a.day BETWEEN p.payday - 6 AND p.payday), 0) * w.rate_paise)
                        - coalesce((SELECT sum(x.amount_paise) FROM wage_payments x WHERE x.worker_id = w.id AND x.kind = 'advance' AND x.paid_on BETWEEN p.payday - 6 AND p.payday), 0)
      WHEN 'piece' THEN coalesce((SELECT sum(e.good) FROM work_entries e WHERE e.worker_id = w.id AND e.day BETWEEN p.payday - 6 AND p.payday), 0) * w.rate_paise
                        - coalesce((SELECT sum(x.amount_paise) FROM wage_payments x WHERE x.worker_id = w.id AND x.kind = 'advance' AND x.paid_on BETWEEN p.payday - 6 AND p.payday), 0)
      ELSE coalesce(w.weekly_payout_paise, 0)
    END AS amount
  FROM workers w CROSS JOIN paydays p
  WHERE w.name IN ('Manoj Deshmukh', 'Ajay Kulkarni', 'Imran Shaikh', 'Ramesh Patil', 'Suresh Jadhav', 'Pooja More', 'Sunita Pawar', 'Raju Gaikwad', 'Vikas Shinde')
    AND (w.started_on IS NULL OR w.started_on <= p.payday) AND (w.left_on IS NULL OR w.left_on >= p.payday - 6)
)
INSERT INTO wage_payments (worker_id, kind, amount_paise, paid_on, payday, note, created_by)
SELECT worker_id, 'weekly', amount, payday, payday, 'Demo', 'demo-seed' FROM due
WHERE amount > 0
  AND NOT EXISTS (SELECT 1 FROM wage_payments x WHERE x.worker_id = due.worker_id AND x.kind = 'weekly' AND x.payday = due.payday);

-- Month-end salary: salary less that month's Tuesday payouts and advances.
WITH months AS (SELECT m::date AS m FROM generate_series(date '2026-07-01', date '2026-09-01', interval '1 month') m),
bal AS (
  SELECT w.id AS worker_id, to_char(mo.m, 'YYYY-MM') AS for_month, (mo.m + interval '1 month' - interval '1 day')::date AS paid_on,
    w.rate_paise
      - coalesce((SELECT sum(x.amount_paise) FROM wage_payments x WHERE x.worker_id = w.id AND x.kind = 'weekly' AND x.payday >= mo.m AND x.payday < mo.m + interval '1 month'), 0)
      - coalesce((SELECT sum(x.amount_paise) FROM wage_payments x WHERE x.worker_id = w.id AND x.kind = 'advance' AND x.paid_on >= mo.m AND x.paid_on < mo.m + interval '1 month'), 0) AS amount
  FROM workers w CROSS JOIN months mo
  WHERE w.pay_type = 'salary' AND w.name IN ('Manoj Deshmukh', 'Ajay Kulkarni', 'Imran Shaikh', 'Ramesh Patil', 'Suresh Jadhav', 'Pooja More', 'Sunita Pawar', 'Raju Gaikwad', 'Vikas Shinde')
)
INSERT INTO wage_payments (worker_id, kind, amount_paise, paid_on, for_month, note, created_by)
SELECT worker_id, 'salary', amount, paid_on, for_month, 'Demo', 'demo-seed' FROM bal
WHERE amount > 0
  AND NOT EXISTS (SELECT 1 FROM wage_payments x WHERE x.worker_id = bal.worker_id AND x.kind = 'salary' AND x.for_month = bal.for_month);

COMMIT;
